import SwiftUI

/// The schools of creed: what aqeedah is, why there is only one, where each school stands (the Athari
/// creed alone correct, the Ash'aris and Maturidis in error but Muslims, the sects outside), the creed of
/// the Salaf, the schools of kalam and how the Ash'aris and Maturidis differ, and the Khawarij,
/// Qadariyyah and Jahmiyyah with the Salaf's verdicts, doctrine apart from person. Sits beneath the
/// Madhahib of Fiqh in the Historical & Biographical list.
struct AqeedahMadhabView: View {
    var body: some View {
        let _ = RenderCounter.hit("AqeedahMadhabView")
        List {
            Group {
                ArticleSectionsView(sections: Self.sections)

                ArticleSourcesSection(article: "AqeedahMadhabView")
            }
            .themedListRowBackground()
        }
        .navigationTitle("Madhahib of Aqeedah")
        .englishArticle().selectableArticleList(article: "AqeedahMadhabView")
    }

    static let sections: [ArticleSection] = [
        ArticleSection("SUMMARY", [
            .text("In short: fiqh may have several valid opinions, but aqeedah is one. The Athari creed, the creed of the Salaf, is the only correct creed: the creed of the Prophet, his Companions, and every prophet before him. The Ash'ari and Maturidi schools are later schools of kalam that erred in parts of it, above all in the attributes of Allah; they are not a second valid creed, but their followers are Muslims, not disbelievers, and are counted within Ahl as-Sunnah in its broad sense. The sects outside it are another matter: the Salaf judged the core doctrines of the Jahmiyyah and of the first Qadariyyah to be disbelief, and every school disavows the Mu'tazilah and the Khawarij."),
        ]),
        ArticleSection("WHAT IS AQEEDAH?", [
            .markdown("**Aqeedah (عَقِيدَة)** comes from the root **ع-ق-د**, “to tie” or “to knot.” The **aqd (عَقد)** is a knot, and a **contract** is called an aqd because it binds. Aqeedah is what the heart is knotted upon: the beliefs a Muslim holds with certainty about Allah, His angels, His books, His messengers, the Last Day, and the divine decree."),
            .markdown("It is the answer to “what do you believe?”, as opposed to **fiqh (فِقه)**, “understanding,” which answers “what do you do, and how?”: prayer, fasting, trade, marriage, and the rest of the practical rulings."),
            .ayah("2:285", words: 0...19),
            .text("When Jibril (peace be upon him) asked the Prophet (peace be upon him) about faith, he answered:"),
            .hadith("muslim:8a", cite: "Sahih Muslim 8", arabic: 273...284, english: [409...442]),
        ]),
        ArticleSection("ONE AQEEDAH, MANY FIQH OPINIONS", [
            .text("Fiqh can carry more than one valid answer. The Companions (may Allah be pleased with them) themselves differed in fiqh in the Prophet’s own lifetime, and he approved both sides. After the Battle of the Trench he said:"),
            .hadith("bukhari:946", cite: "Sahih al-Bukhari 946", arabic: 16...66, english: [16...93]),
            .text("One group took his words literally and delayed the prayer; the other understood them to mean “hurry,” and prayed on time. Both were sincere, both reasoned from his command, and he rebuked neither. This is fiqh: sincere, qualified effort in understanding, where more than one answer can be acceptable."),
            .text("Aqeedah is different. There is no “two valid opinions” on whether Allah is One, whether the Quran is His speech, or whether He will be seen in Paradise. Creed is fixed by revelation, and it never changed from the first prophet to the last:"),
            .ayah("21:25"),
            .ayah("42:13", words: 1...23),
            .text("The Prophet (peace be upon him) said:"),
            .hadith("bukhari:3443", cite: "Sahih al-Bukhari 3443, Sahih Muslim 2365", arabic: 40...46, english: [26...39]),
            .text("So Nuh, Ibrahim, Musa, Isa, and Muhammad (peace be upon them all) had one and the same aqeedah, with different laws (shari‘ah). Abu Bakr, Umar, Uthman, Ali, Ibn Mas‘ud, Ibn Abbas, Aisha, and all the senior Companions had one creed; the Ahlul Bayt (the Prophet’s wives, Ali, Fatimah, al-Hasan, al-Husayn, and the rest of his household) had that same creed; and the Companions differed among themselves in fiqh without ever splitting over creed. That single creed is what the schools below are measured against."),
        ]),
        ArticleSection("THE SCHOOLS AND WHERE THEY STAND", [
            .text("Before the details, the verdict, so that nothing below is misread. Measured against that one creed, the schools fall into three ranks."),
            .callout("The creed of the Prophet (peace be upon him) and his Companions, taken from the Quran, the Sunnah, and the reports of the Salaf, and held by the four imams. It is the **only correct creed**, the one every other school is measured against, and its people are Ahl as-Sunnah in the full sense.", title: "Correct: the Athari creed", icon: "checkmark.seal.fill"),
            .callout("Later schools of kalam that agree with the Salaf in much and depart from them in the attributes of Allah, His speech, the definition of faith, and the place of reason. Where they depart they are wrong, and they are **not a second valid creed** beside the Athari one; but their followers are **Muslims, not disbelievers**, the scholars count them within Ahl as-Sunnah in the broad sense, and they are the nearest of the theologians to the Sunnah.", title: "In error, still Muslims: the Ash‘aris and Maturidis", icon: "exclamationmark.triangle.fill"),
            .callout("The Khawarij, the Qadariyyah, the Jahmiyyah, the Mu‘tazilah, and the Rafidah, whom every school of Ahl as-Sunnah disavows. They are not all of one weight: the Salaf judged the core doctrines of the **Jahmiyyah**, who denied the names and attributes of Allah, and of the **first Qadariyyah**, who denied that Allah knew deeds before they happened, to be **disbelief itself**, while the Khawarij and the later Qadariyyah were judged misguided innovators who had not left Islam.", title: "Outside Ahl as-Sunnah: the sects", icon: "xmark.octagon.fill"),
            .text("The two senses of “Ahl as-Sunnah” are Shaykh al-Islam Ibn Taymiyyah’s (may Allah have mercy on him):"),
            .quote(text: "“The term Ahl as-Sunnah is meant for whoever affirms the caliphate of the three caliphs, and then every sect enters it except the Rafidah; and it is meant for the people of hadith and of the pure Sunnah, and then none enters it but the one who affirms the attributes of Allah the Exalted and says that the Quran is not created and that Allah will be seen in the Hereafter, and affirms the decree, with the other foundations known among the people of hadith and the Sunnah” (Ibn Taymiyyah, Minhaj as-Sunnah an-Nabawiyyah 2/221).", arabic: "فَلَفظُ أَهلِ السُّنَّةِ يُرَادُ بِهِ مَن أَثبَتَ خِلَافَةَ الخُلَفَاءِ الثَّلَاثَةِ، فَيَدخُلُ فِي ذَلِكَ جَمِيعُ الطَّوَائِفِ إِلَّا الرَّافِضَةَ، وَقَد يُرَادُ بِهِ أَهلُ الحَدِيثِ وَالسُّنَّةِ المَحضَةِ، فَلَا يَدخُلُ فِيهِ إِلَّا مَن يُثبِتُ الصِّفَاتِ لِلَّهِ تَعَالَى، وَيَقُولُ: إِنَّ القُرآنَ غَيرُ مَخلُوقٍ، وَإِنَّ اللَّهَ يُرَى فِي الآخِرَةِ، وَيُثبِتُ القَدَرَ، وَغَيرَ ذَلِكَ مِنَ الأُصُولِ المَعرُوفَةِ عِندَ أَهلِ الحَدِيثِ وَالسُّنَّةِ", dimmed: true),
            .text("Of the Ash‘aris he wrote, in the same passage in which he called them Murji’ah in the names and rulings of faith and Jabriyyah in the decree, that “they are, on the whole, the nearest of the theologians to the way of Ahl as-Sunnah and hadith” (Majmu‘ al-Fatawa 6/55). The scholars of our time say the same. Shaykh Abd al-Aziz ibn Baz (may Allah have mercy on him) said:"),
            .quote(text: "“The Ash‘aris are of Ahl as-Sunnah in most matters, but they are not of them in their reinterpretation of the attributes. They are not disbelievers; among them are imams, scholars, and good people, but they erred in reinterpreting some of the attributes” (Majmu‘ Fatawa Ibn Baz 28/257).", arabic: "الأَشَاعِرَةُ مِن أَهلِ السُّنَّةِ فِي غَالِبِ الأُمُورِ، وَلَكِنَّهُم لَيسُوا مِنهُم فِي تَأوِيلِ الصِّفَاتِ، وَلَيسُوا بِكُفَّارٍ، بَل فِيهِمُ الأَئِمَّةُ وَالعُلَمَاءُ وَالأَخيَارُ، وَلَكِنَّهُم غَلِطُوا فِي تَأوِيلِ بَعضِ الصِّفَاتِ", dimmed: true),
            .text("And Shaykh Muhammad ibn Salih al-Uthaymin (may Allah have mercy on him) closed the door on calling them a second valid creed:"),
            .quote(text: "“The Ash‘aris, for example, and the Maturidis are not counted among Ahl as-Sunnah wal-Jama‘ah in this chapter, because they oppose what the Prophet (peace be upon him) and his Companions were upon in taking the attributes of Allah, Glorified and Exalted, upon their reality … and so whoever says that Ahl as-Sunnah wal-Jama‘ah are three, Salafis, Ash‘aris, and Maturidis, is mistaken; that is an error” (Ibn al-Uthaymin, Sharh al-‘Aqidah al-Wasitiyyah 1/53).", arabic: "فَالأَشَاعِرَةُ مَثَلًا وَالمَاتُرِيدِيَّةُ لَا يُعَدُّونَ مِن أَهلِ السُّنَّةِ وَالجَمَاعَةِ فِي هَذَا البَابِ، لِأَنَّهُم مُخَالِفُونَ لِمَا كَانَ عَلَيهِ النَّبِيُّ صَلَّى اللَّهُ عَلَيهِ وَسَلَّمَ وَأَصحَابُهُ فِي إِجرَاءِ صِفَاتِ اللَّهِ سُبحَانَهُ وَتَعَالَى عَلَى حَقِيقَتِهَا … وَلِهَذَا يُخطِئُ مَن يَقُولُ: إِنَّ أَهلَ السُّنَّةِ وَالجَمَاعَةِ ثَلَاثَةٌ: سَلَفِيُّونَ، وَأَشعَرِيُّونَ، وَمَاتُرِيدِيُّونَ، فَهَذَا خَطَأٌ", dimmed: true),
            .text("“This chapter” is the attributes of Allah, and the point of both statements is the same: Ahl as-Sunnah is not a family of three creeds with the Athari one among them. It is the Athari creed, and the others are measured by how near to it or far from it they stand."),
        ]),
        ArticleSection("TWO ROADS: ATHAR AND KALAM", [
            .text("Every school of creed in Islamic history walks one of two roads."),
            .markdown("**1. The road of athar (أَثَر, “narration” or “track”)**: creed is taken from the Quran, the Sunnah, and the reports of the Companions, and the mind submits to the text. Whatever Allah affirmed for Himself is affirmed as He said it, without asking how, and whatever He negated is negated."),
            .markdown("**2. The road of kalam (عِلم الكَلَام, from the root ك-ل-م, speech: “speculative theology,” named for the arguing it consists of)**: creed is argued from rational premises, many of them inherited from Greek philosophy, which entered Muslim lands through the translation movement of the second and third centuries AH. The text is then reinterpreted to fit the conclusions of reason."),
            .text("The Salaf (السَّلَف, from the root س-ل-ف: those who have gone before, meaning the first three generations) warned against the second road before it even had a name. Allah (Glorified and Exalted be He) says:"),
            .ayah("3:7", words: 13...25),
            .text("Aisha (may Allah be pleased with her) said the Prophet (peace be upon him) recited this verse and then said:"),
            .hadith("bukhari:4547", cite: "Sahih al-Bukhari 4547", arabic: 74...85, english: [119...148]),
            .text("The Prophet (peace be upon him) also said:"),
            .hadith("abudawud:4603", cite: "Sunan Abi Dawud 4603; graded hasan sahih by al-Albani", arabic: 30...33, english: [4...9]),
            .text("When a man asked Imam Malik (may Allah have mercy on him) how Allah rose over the Throne, he answered with the rule that defines the road of athar:"),
            .quote(text: "“The rising is not unknown, the ‘how’ is not comprehensible, believing in it is obligatory, and asking about it is an innovation” (al-Bayhaqi, al-Asma' was-Sifat 867; al-Lalaka'i 664).", arabic: "الِاستِوَاءُ غَيرُ مَجهُولٍ، وَالكَيفُ غَيرُ مَعقُولٍ، وَالإِيمَانُ بِهِ وَاجِبٌ، وَالسُّؤَالُ عَنهُ بِدعَةٌ", dimmed: true),
            .text("Imam al-Shafi‘i (may Allah have mercy on him) said of the people of kalam:"),
            .quote(text: "“My ruling on the people of kalam is that they be beaten with palm branches and sandals and paraded among the clans and tribes, and it be said: this is the reward of one who left the Book and the Sunnah and took up kalam” (Ibn Abi Hatim, Adab al-Shafi'i 182; adh-Dhahabi, Siyar 10/29).", arabic: "حُكمِي فِي أَهلِ الكَلَامِ أَن يُضرَبُوا بِالجَرِيدِ وَالنِّعَالِ، وَيُطَافَ بِهِم فِي العَشَائِرِ وَالقَبَائِلِ، وَيُقَالَ: هَذَا جَزَاءُ مَن تَرَكَ الكِتَابَ وَالسُّنَّةَ وَأَخَذَ فِي الكَلَامِ", dimmed: true),
        ]),
        ArticleSection("THE CREED OF THE SALAF: THE ATHARI SCHOOL", [
            .markdown("The **Athari (الأَثَرِي)** creed is named after **athar**, narration, not after a person. Its people were called **Ahl al-Hadith (أَهل الحَدِيث)**, **Ahl al-Athar (أَهل الأَثَر)**, and **Ahl as-Sunnah (أَهل السُّنَّة)**. It is simply the creed of the Prophet (peace be upon him) and his Companions, written down and defended when the sects appeared."),
            .markdown("Its imam is **Ahmad ibn Hanbal (أَحمَدُ بنُ حَنبَلٍ)** (164–241 AH / 780–855 CE), the **Imam of Ahl as-Sunnah**, who left behind both a madhhab of fiqh, the Hanbali school, and one of the earliest written creeds of Ahl as-Sunnah, the **Usul as-Sunnah**, dictated to his student Abdus ibn Malik al-Attar. He did not invent a creed; he preserved one. His own words describe what the school is:"),
            .quote(text: "“The foundations of the Sunnah with us are: holding fast to what the Companions of the Messenger of Allah were upon, taking them as an example, abandoning innovations; and every innovation is misguidance” (Ahmad ibn Hanbal, Usul as-Sunnah; al-Lalaka'i 317).", arabic: "أُصُولُ السُّنَّةِ عِندَنَا: التَّمَسُّكُ بِمَا كَانَ عَلَيهِ أَصحَابُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيهِ وَسَلَّمَ، وَالِاقتِدَاءُ بِهِم، وَتَركُ البِدَعِ، وَكُلُّ بِدعَةٍ فَهِيَ ضَلَالَةٌ", dimmed: true),
            .markdown("**The Mihnah (المِحنَة, “the Inquisition”)**: in 218 AH the caliph al-Ma’mun, who had declared the Mu‘tazili doctrine that the Quran is created in 212 AH, began forcing the scholars to profess it. Under him, al-Mu‘tasim, and al-Wathiq (218–234 AH), Imam Ahmad was chained, imprisoned for about two years, and flogged until he lost consciousness, and he refused to say a word other than what the Quran and Sunnah said. When they demanded he adopt their creed, he replied:"),
            .quote(text: "“Give me something from the Book of Allah or the Sunnah of the Messenger of Allah so that I may say it” (Hanbal ibn Ishaq, Dhikr Mihnat al-Imam Ahmad; adh-Dhahabi, Siyar 11/241).", arabic: "أَعطُونِي شَيئًا مِن كِتَابِ اللَّهِ أَو سُنَّةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيهِ وَسَلَّمَ حَتَّى أَقُولَ بِهِ", dimmed: true),
            .markdown("He was released from prison in 221 AH after the flogging, kept to his house under al-Wathiq, and the Mihnah was ended by al-Mutawakkil in 234 AH with the Sunnah intact; the Muslims called him the **Defender of the Sunnah**. Because he did not bend when almost everyone else did, the creed of the Salaf came to be identified with him, though it is older than him and belongs to no one."),
            .markdown("**Its method**: the names and attributes of Allah are affirmed as they came, without **tahrif (تَحرِيف)** (changing the meaning), **ta‘til (تَعطِيل)** (denying them), **takyif (تَكيِيف)** (asking how), or **tamthil (تَمثِيل)** (likening Him to creation). The measure is:"),
            .ayah("42:11", words: 13...18),
            .ayah("7:54", words: 0...13),
            .markdown("So Allah is affirmed to be above His Throne as He said, without asking how, exactly as Imam Malik answered. The Quran is the uncreated speech of Allah. The believers will see their Lord in Paradise. Faith is belief, statement, and action; it increases and decreases. No Muslim is declared a disbeliever for a sin. All the Companions are loved and none is cursed. This is the creed of the four imams of fiqh, not only Ahmad: **Abu Ja‘far al-Tahawi (الطَّحَاوِي)** (d. 321 AH), a Hanafi, opened his famous creed by describing it as the creed of Ahl as-Sunnah wal-Jama‘ah according to the madhhab of Abu Hanifah, Abu Yusuf, and Muhammad ibn al-Hasan ash-Shaybani."),
            .markdown("**Its books**: Usul as-Sunnah of Imam Ahmad; as-Sunnah of his son Abdullah; Khalq Af‘al al-‘Ibad of al-Bukhari; Sharh as-Sunnah of al-Barbahari (d. 329 AH); al-Ibanah of Ibn Battah (d. 387 AH); Sharh Usul I‘tiqad Ahl as-Sunnah of al-Lalaka’i (d. 418 AH); al-Aqidah al-Tahawiyyah; Lum‘at al-I‘tiqad of Ibn Qudamah (d. 620 AH); and al-Aqidah al-Wasitiyyah of Ibn Taymiyyah (d. 728 AH)."),
        ]),
        ArticleSection("THE SCHOOLS OF KALAM", [
            .text("Three schools took the road of kalam. The Mu‘tazilah are outside Ahl as-Sunnah altogether; the Ash‘aris and the Maturidis are wrong wherever they left the Salaf, yet they are Muslims, counted within Ahl as-Sunnah in its broad sense, as set out under The Schools and Where They Stand."),
            .markdown("**1. The Mu‘tazilah (المُعتَزِلَة)**, founded by **Wasil ibn Ata (وَاصِلُ بنُ عَطَاءٍ)** (80–131 AH). He withdrew (**i‘tazala**) from the circle of the great Successor al-Hasan al-Basri in Basrah over the ruling on the major sinner, and his followers took the name. They held that the Quran is created, that Allah is knowing and powerful “by His essence” with no attribute additional to it, which Ahl as-Sunnah rightly called a denial of the attributes, that He will not be seen in the Hereafter, and that man creates his own actions independently of Allah’s decree, so that the Salaf counted them among the **Qadariyyah (القَدَرِيَّة)**, whose section follows below. It was their creed that al-Ma’mun imposed in the Mihnah and that Imam Ahmad was imprisoned for refusing. They placed reason above revelation, and every school of Ahl as-Sunnah, Athari, Ash‘ari, and Maturidi alike, rejects them."),
            .markdown("**2. The Ash‘ariyyah (الأَشعَرِيَّة)**, named after **Abu al-Hasan Ali ibn Isma‘il al-Ash‘ari (أَبُو الحَسَن الأَشعَرِي)** (260–324 AH / 874–936 CE) of Basrah and Baghdad. He is a descendant of the Companion Abu Musa al-Ash‘ari (may Allah be pleased with him), not to be confused with him. Abu al-Hasan spent about forty years as a Mu‘tazili theologian, the student and stepson of their leader al-Jubba’i, before renouncing the Mu‘tazilah publicly in the mosque of Basrah around 300 AH. He then passed through a middle period in which he followed Ibn Kullab, affirming some attributes by rational proof and reinterpreting others, and ended in a final period in which he wrote **al-Ibanah ‘an Usul al-Diyanah** and declared:"),
            .quote(text: "“The position we hold and the religion we follow is: holding fast to the Book of our Lord and the Sunnah of our Prophet and what is narrated from the Companions, the Successors, and the imams of hadith … and we say what Abu Abdullah Ahmad ibn Muhammad ibn Hanbal said, and we oppose whatever opposes his statement” (al-Ash'ari, al-Ibanah, p. 20).", arabic: "قَولُنَا الَّذِي نَقُولُ بِهِ وَدِيَانَتُنَا الَّتِي نَدِينُ بِهَا: التَّمَسُّكُ بِكِتَابِ رَبِّنَا وَبِسُنَّةِ نَبِيِّنَا صَلَّى اللَّهُ عَلَيهِ وَسَلَّمَ، وَمَا رُوِيَ عَنِ الصَّحَابَةِ وَالتَّابِعِينَ وَأَئِمَّةِ الحَدِيثِ … وَبِمَا كَانَ يَقُولُ بِهِ أَبُو عَبدِ اللَّهِ أَحمَدُ بنُ مُحَمَّدِ بنِ حَنبَلٍ قَائِلُونَ، وَلِمَا خَالَفَ قَولَهُ مُخَالِفُونَ", dimmed: true),
            .text("The school that carries his name did not settle on this final position. It built on his middle period and on the theologians who came after him (al-Juwayni, al-Ghazali, and al-Razi), who went further in reinterpreting the attributes and in adopting kalam; al-Baqillani, the earliest of them, still affirmed the attributes of the Hand and the Face without ta’wil. Many great scholars of fiqh and hadith held the Ash‘ari creed, among them al-Nawawi, Ibn Hajar, and al-Qurtubi, and Ahl as-Sunnah honour them and benefit from their works while disagreeing with them where they departed from the Salaf. And the one who follows Abu al-Hasan himself to the end of his life arrives at the creed of Imam Ahmad."),
            .markdown("**3. The Maturidiyyah (المَاتُرِيدِيَّة)**, named after **Abu Mansur Muhammad ibn Muhammad al-Maturidi (أَبُو مَنصُور المَاتُرِيدِي)** (d. 333 AH / 944 CE) of Maturid near Samarqand, a Hanafi jurist and the author of Kitab at-Tawhid. He was al-Ash‘ari’s contemporary, answering the same Mu‘tazilah from the far east of the Muslim world with the same tools of kalam, and his school presents itself as the creed of Abu Hanifah. It spread with the Hanafi madhhab through Central Asia, the Ottoman lands, and the Indian subcontinent, as the Ash‘ari school spread with the later Shafi‘is and Malikis. Yet Abu Hanifah’s own words, quoted in this article, affirm that Allah is above His Throne and that the Quran is not created, and his al-Fiqh al-Akbar says plainly that Musa heard the speech of Allah; on these the later school left its own imam. Its assessment is the same as the Ash‘aris’, and how the two differ is set out next."),
            .text("Notice the difference in the names. The Ash‘ari and Maturidi schools are named after two men who lived three hundred years after the Prophet (peace be upon him); the Mu‘tazilah after an act of withdrawal. The Athari creed is named after nothing but the narrations themselves, because it existed before any of these men were born."),
        ]),
        ArticleSection("ASH‘ARIS AND MATURIDIS: HOW THEY DIFFER", [
            .text("The two schools grew up in the same generation, al-Ash‘ari in Basrah and Baghdad and al-Maturidi in Samarqand, to answer the same Mu‘tazilah with the same tools, and they agree far more than they differ. Taj ad-Din as-Subki (d. 771 AH), an Ash‘ari, counted thirteen points between his school and the Hanafis, six of substance and the rest only of wording, and said none of them calls for either side to declare the other innovators (Tabaqat ash-Shafi‘iyyah al-Kubra 3/378); later Hanafi authors listed forty and fifty by dividing the same questions more finely. At a glance:"),
            .versus(ArticleVersus.Side("Ash‘ari", arabic: "الأَشَاعِرَة", caption: "**Seven** eternal attributes of meaning. Nothing is good or obligatory **before revelation**. Allah’s acts have **no purpose** behind them. He **may** burden a soul beyond its capacity. Musa **heard the eternal speech** itself."), ArticleVersus.Side("Maturidi", arabic: "المَاتُرِيدِيَّة", caption: "**Eight**, adding **takwin**, bringing into being. **Reason** knows good and evil and obliges knowing Allah. Allah acts **with wisdom**. He **does not** burden beyond capacity. Musa heard **created sounds** expressing the speech."), quranic: false),
            .text("The differences that matter, each with where the Salaf stand:"),
            .step("1. **Reason and obligation.** The Ash‘aris say nothing is good or evil, obligatory or forbidden, except by revelation. The Maturidis say reason itself perceives good and evil, and that knowing Allah is obligatory by reason even before a messenger comes; that was al-Maturidi’s position and Samarqand’s, while the Hanafis of Bukhara sided with the Ash‘aris. **The Salaf** hold that reason and the fitrah do recognise much of good and evil, but that no one is punished before the message reaches him (Ibn Taymiyyah, Majmu‘ al-Fatawa 8/428–435):"),
            .ayah("17:15", words: 15...20),
            .step("2. **Wisdom in Allah’s acts.** The Ash‘aris deny that Allah acts for a purpose, lest He be thought to need it; the Maturidis affirm that He acts with wisdom. **The Salaf** affirm it, and here the Maturidis are with them: Ibn Taymiyyah noted that the Hanafis are of Ahl as-Sunnah in affirming the decree, and that most of them affirm the reasons and benefits in Allah’s acts (Minhaj as-Sunnah 1/143). Allah says:"),
            .ayah("23:115"),
            .ayah("51:56"),
            .step("3. **Takwin, bringing into being.** The Maturidis count takwin as an eternal attribute distinct from power, which gives them eight attributes; the Ash‘aris count seven, and make Allah’s creating nothing but His power attaching to the thing created, so that the creating is the created. **The Salaf** say the creating is other than the created, which al-Bukhari reported as the position of the scholars, so the Maturidis are nearer here; but they made it one eternal act, where the Salaf affirm that Allah does what He wills when He wills (Ibn Taymiyyah, Majmu‘ al-Fatawa 5/379, 16/376)."),
            .step("4. **How Musa heard Allah.** Both schools hold that Allah’s speech is one eternal meaning in Himself, without letters or sound. The Ash‘aris say that eternal speech can be heard and that Musa heard it; the Maturidis say it cannot be heard, and al-Maturidi wrote that Allah made Musa hear it through letters He created and a sound He brought into being (Kitab at-Tawhid). **The Salaf** say Allah speaks when He wills with speech that is heard, and that Musa heard Allah Himself:"),
            .ayah("4:164", words: 10...13),
            .step("5. **Burdening beyond capacity, and punishing the obedient.** The Ash‘aris hold that Allah may, as a matter of reason, charge a soul with what it cannot bear and punish one who obeyed Him, since everything is His; the Maturidis deny both. **The Salaf** deny both because Allah denied them of Himself, and in a hadith qudsi He says, “I have forbidden injustice for Myself” (Sahih Muslim 2577):"),
            .ayah("2:286", words: 0...5),
            .ayah("68:35-36"),
            .step("6. **Faith, and saying “I am a believer, in sha’ Allah.”** The Maturidis, with the Hanafis, define faith as assent of the heart, with or without the testimony of the tongue, say it neither increases nor decreases, and forbid the phrase as a doubt; the Ash‘aris also make faith assent, but permit the phrase, looking to the state in which a person will die. **The Salaf** say faith is belief, statement, and action, rising and falling, and they said “in sha’ Allah” because complete faith includes doing everything commanded, which no one claims for himself (Ibn Taymiyyah, Majmu‘ al-Fatawa 7/417); the question on major sins below gives the verses."),
            .step("7. **The servant’s act.** The Ash‘aris speak of kasb, “acquisition,” in which the servant’s power has no real effect, which is why Ibn Taymiyyah counted them Jabriyyah in the decree (Majmu‘ al-Fatawa 6/55); the Maturidis speak of ikhtiyar, a real choice in the servant, though as-Subki held the two words to mean one thing. **The Salaf** say the servant has a real will and power that truly bring about his act, and that Allah created both, as the verses of at-Takwir say (Quran 81:28–29, below)."),
            .text("Weighed against the Salaf, neither school is simply the nearer one. The Maturidis stand closer on wisdom, on takwin, on reason’s grasp of good and evil, and on the limits of the burden. The Ash‘aris stand closer in permitting “in sha’ Allah,” and their early imams, al-Ash‘ari himself and al-Baqillani, affirmed the Hand, the Face, and the rising as the Salaf did; Ibn Taymiyyah said the later Ash‘aris drew nearer to the Mu‘tazilah and “opposed their own first ones” (at-Tis‘iniyyah 1/271)."),
        ]),
        ArticleSection("WHERE BOTH LEAVE THE SALAF", [
            .text("The differences above are real, but the two schools share the errors that separate them from the Salaf, and these weigh far more:"),
            .bullet("**The proof of Allah taken from kalam**, the argument from the origination of bodies, instead of the fitrah and the signs the Quran points to; and from it the denial that Allah does anything by His will at a time, such as His rising over the Throne, His descent, and His speaking when He wills."),
            .bullet("**The speech of Allah made one eternal inner meaning**, of which the recited Quran is only an expression (see the question on the Quran below)."),
            .bullet("**The Hand, the Face, the Eyes, the rising, and the descent** reinterpreted (ta’wil) or emptied of their meaning (tafwid) by their later scholars (see the four errors in the Key Terms)."),
            .bullet("**Allah’s being above His creation** denied by most of their later scholars, who say He is neither inside the world nor outside it (see “Where is Allah?” below)."),
            .bullet("**Faith defined as assent**, with deeds outside it."),
            .bullet("**Single-chain hadith refused as proof in creed** by many of them (see the question below), and **reason given the last word** wherever it seems to clash with a text."),
            .text("This is why the disagreement with them is not a quarrel over words, and why it is still argued with evidence and good manners, as the scholars quoted above argued it."),
        ]),
        ArticleSection("THE REJECTED SECTS", [
            .markdown("Outside the three schools stand the sects that Ahl as-Sunnah of every school disavow: the Mu‘tazilah above, the **Khawarij (الخَوَارِج)**, and the two sects with sections of their own below, the Qadariyyah and the Jahmiyyah. The Khawarij came first."),
            .text("The Khawarij, “those who went out,” were the first sect in Islam. They broke away from Ali (may Allah be pleased with him) after the arbitration at Siffin in 37 AH, raising the slogan “no judgement but Allah’s,” declared Muslims disbelievers for major sins, rebelled against the Muslim rulers, and finally assassinated Ali in 40 AH. They did not follow kalam; they followed their own hasty reading of the Quran, without the Companions. The Prophet (peace be upon him) described them before they appeared. When Dhul-Khuwaysirah said to him, “Be just,” he said:"),
            .hadith("bukhari:3610", cite: "Sahih al-Bukhari 3610, Sahih Muslim 1064", arabic: 79...103, english: [76...131]),
            .text("Ali (may Allah be pleased with him) narrated:"),
            .hadith("bukhari:3611", cite: "Sahih al-Bukhari 3611, Sahih Muslim 1066", arabic: 59...80, english: [49...104]),
            .hadith("ibnmajah:173", cite: "Sunan Ibn Majah 173; graded sahih by al-Albani", arabic: 27...29, english: [5...11]),
            .text("When they told Ali, “There is no judgement but Allah’s,” he replied:"),
            .hadith("muslim:1066g", cite: "Sahih Muslim 1066", arabic: 61...65, english: [34...47]),
            .text("Every group that declares Muslims disbelievers for sins and takes up arms against them on that basis walks the path of the Khawarij, whatever it calls itself today. Ahl as-Sunnah hold the opposite: the Prophet (peace be upon him) said:"),
            .hadith("bukhari:6103", cite: "Sahih al-Bukhari 6103, Sahih Muslim 60", arabic: 40...49, english: [4...23]),
            .text("And Ahl as-Sunnah did not answer the Khawarij with their own weapon. Ali himself, who fought them, did not declare them disbelievers. He was asked about the people of Nahrawan, whether they were polytheists, then whether they were hypocrites, then what they were, and he answered:"),
            .quote(text: "“From shirk they fled … The hypocrites do not remember Allah except a little … A people who rebelled against us” (Musannaf Ibn Abi Shaybah 40753, graded sahih by its editor).", arabic: "مِنَ الشِّركِ فَرُّوا … إِنَّ المُنَافِقِينَ لَا يَذكُرُونَ اللَّهَ إِلَّا قَلِيلًا … قَومٌ بَغَوا عَلَينَا", dimmed: true),
            .text("So most of the scholars of Ahl as-Sunnah held the Khawarij to be sinful Muslims to whom the rulings of Islam apply, and al-Khattabi reported the agreement of the scholars that, for all their misguidance, they are one of the sects of the Muslims; a minority, among them al-Qadi Iyad and al-Qurtubi, inclined to declaring them disbelievers because of the hadith of their passing out of the religion (Ibn Hajar, Fath al-Bari 12/300)."),
            .markdown("The Salaf also warned against the **Murji’ah (المُرجِئَة)**, who said sins do not harm faith, and the **Rafidah (الرَّافِضَة)**, who rejected the Companions; see “Answering the Shia” and the other articles under Salafiyyah below. The Qadariyyah and the Jahmiyyah, whose errors struck at the heart of the creed, come next."),
        ]),
        ArticleSection("THE QADARIYYAH: THE DENIERS OF THE DECREE", [
            .markdown("The **Qadariyyah (القَدَرِيَّة)** are named after **qadar (قَدَر)**, the decree, which they denied. They were the first sect to speak against a pillar of faith itself, and they appeared while Companions were still alive. The answer to them is built on the four levels of the decree that Ibn al-Qayyim set out, saying that whoever does not believe in them has not believed in the decree: **Allah’s knowledge** of everything before it is; **His writing** of it; **His will**, without which nothing happens; and **His creating** of everything, the servants’ acts included (Shifa’ al-‘Alil, chapter 10)."),
            .markdown("**The first Qadariyyah** denied the first two levels: Allah, they said, does not know deeds until they are done, and the matter is “new” (unuf). The first to say it was **Ma‘bad al-Juhani (مَعبَدٌ الجُهَنِيُّ)** in Basrah, in the time of the Companions; al-Awza‘i said he took it from a man of Iraq named Susan, a Christian who embraced Islam and then returned to Christianity. Ma‘bad fought al-Hajjaj in the revolt of Ibn al-Ash‘ath and was put to death before 90 AH (adh-Dhahabi, Siyar 4/185–187). When word of him reached Abdullah ibn Umar (may Allah be pleased with them both), he gave the Companions’ answer:"),
            .hadith("muslim:8a", cite: "Sahih Muslim 8", arabic: 132...162, english: [132...223]),
            .markdown("After him came **Ghaylan of Damascus (غَيلَانُ الدِّمَشقِيُّ)**. Umar ibn Abd al-Aziz (may Allah have mercy on him) debated him and put the whole matter in a sentence:"),
            .quote(text: "“Woe to you, Ghaylan: if you affirm the knowledge [of Allah] you are defeated, and if you deny it you disbelieve; and that you affirm it and are defeated is better for you than that you deny it and disbelieve” (Abdullah ibn Ahmad, as-Sunnah 948; al-Lalaka’i, Sharh Usul I‘tiqad Ahl as-Sunnah 1325).", arabic: "وَيحَكَ يَا غَيلَانُ، إِنَّكَ إِن أَقرَرتَ بِالعِلمِ خُصِمتَ، وَإِن جَحَدتَهُ كَفَرتَ، وَإِنَّكَ إِن تُقِرَّ بِهِ فَتُخصَمَ خَيرٌ لَكَ مِن أَن تَجحَدَهُ فَتَكفُرَ", dimmed: true),
            .text("Ghaylan promised never to speak of it again, went back to it after Umar’s death, and was put to death under Hisham ibn Abd al-Malik; Ibn Awn said, “I saw Ghaylan crucified at the gate of Damascus” (as-Sunnah 949). Several imams of the Salaf made Umar’s words their rule: “Debate the Qadariyyah with knowledge: if they affirm it they are defeated, and if they deny it they disbelieve.” Malik, ash-Shafi‘i, and Ahmad said of the Qadari that if he denies Allah’s knowledge he has disbelieved (Ibn Taymiyyah, Majmu‘ al-Fatawa 23/349; Ibn Rajab, Jami‘ al-‘Ulum wal-Hikam, hadith 2)."),
            .markdown("**The later Qadariyyah** affirmed the first two levels and denied the last two: Allah knew and wrote everything, they said, but He neither wills nor creates the servants’ acts, and each man creates his own. This is the Qadariyyah of the Mu‘tazilah. Ibn Rajab noted that many Qadariyyah affirmed the first level while their extremists, such as Ma‘bad, denied it (Jami‘ al-‘Ulum wal-Hikam, hadith 2), and an-Nawawi related from the writers on the sects that the first kind died out, so that the later Qadariyyah affirm the decree but say good is from Allah and evil from other than Him (Sharh Sahih Muslim 1/154). It is these, Ibn Taymiyyah wrote, whom the Prophet (peace be upon him) called the Magians of this nation (al-‘Aqidah al-Wasitiyyah):"),
            .hadith("abudawud:4691", cite: "Sunan Abi Dawud 4691; graded hasan by al-Albani", arabic: 27...30, english: [4...11]),
            .text("Al-Khattabi explained the likeness: the Magians say there are two origins, light and darkness, good coming from the one and evil from the other; and the Qadariyyah ascribe good to Allah and evil to other than Him, when Allah is the Creator of good and evil and nothing of either happens except by His will (Ma‘alim as-Sunan 4/317)."),
            .text("The texts answer both kinds at once. Allah wrote everything before it happened, as the Companion Ubadah ibn as-Samit taught his son:"),
            .hadith("abudawud:4700", cite: "Sunan Abi Dawud 4700; graded sahih by al-Albani", arabic: 27...99, english: [0...99]),
            .text("When the polytheists of Quraysh came to dispute with the Prophet (peace be upon him) about the decree, Allah revealed (Sahih Muslim 2656):"),
            .ayah("54:48-49"),
            .text("And He created the servants and what they do (Quran 37:96), while their will is real and lies within His (Quran 81:28–29), as the question on the decree below sets out. So the Salaf judged the two kinds differently. The denial of Allah’s knowledge is disbelief, by the word of Ibn Umar and of the imams above; the later Qadariyyah, who affirm the knowledge, are innovators of the gravest kind, but Imam Ahmad’s texts are explicit in refusing to declare them disbelievers, as The Doctrine and the Person below shows."),
        ]),
        ArticleSection("THE JAHMIYYAH: THE DENIERS OF THE ATTRIBUTES", [
            .markdown("The **Jahmiyyah (الجَهمِيَّة)** are named after **Jahm ibn Safwan (جَهمُ بنُ صَفوَانَ)** of Samarqand, secretary to al-Harith ibn Surayj in his revolt in Khurasan (adh-Dhahabi, Siyar 6/26–27). He took his teaching from **al-Ja‘d ibn Dirham (الجَعدُ بنُ دِرهَمٍ)**, the first man recorded as saying it in Islam. Ibn Taymiyyah adds that al-Ja‘d is said to have taken it, through two men, from Labid ibn al-A‘sam, the Jew who worked magic on the Prophet (peace be upon him), though he gives that chain only as “it has been said” (al-Fatwa al-Hamawiyyah, in Majmu‘ al-Fatawa 5/20). The governor Khalid ibn Abdillah al-Qasri put al-Ja‘d to death on the Day of Sacrifice in Wasit, saying from the pulpit:"),
            .quote(text: "“O people, offer your sacrifices, may Allah accept them from you; I am sacrificing al-Ja‘d ibn Dirham, for he claims that Allah did not take Ibrahim as a close friend and did not speak to Musa. Exalted is Allah far above what al-Ja‘d says.” Then he came down and slaughtered him (al-Bukhari, Khalq Af'al al-'Ibad; ad-Darimi, ar-Radd 'ala al-Jahmiyyah; al-Lalaka'i, Sharh Usul I'tiqad Ahl as-Sunnah).", arabic: "أَيُّهَا النَّاسُ ضَحُّوا تَقَبَّلَ اللَّهُ ضَحَايَاكُم، فَإِنِّي مُضَحٍّ بِالجَعدِ بنِ دِرهَمٍ، إِنَّهُ زَعَمَ أَنَّ اللَّهَ لَم يَتَّخِذ إِبرَاهِيمَ خَلِيلًا، وَلَم يُكَلِّم مُوسَى تَكلِيمًا، تَعَالَى اللَّهُ عَمَّا يَقُولُ الجَعدُ عُلُوًّا كَبِيرًا. ثُمَّ نَزَلَ فَذَبَحَهُ", dimmed: true),
            .text("How Jahm came to his doctrine is told in ar-Radd ‘ala az-Zanadiqah wal-Jahmiyyah, attributed to Imam Ahmad. A group of idolaters called the Sumaniyyah asked him whether he had seen his god, heard him, smelled him, or felt and touched him, and to each he said no. He was left so confused that for forty days he did not know whom to worship; in the report al-Bukhari cites from Ibn Shawdhab, he stayed forty days not praying (Khalq Af‘al al-‘Ibad). Then he answered them with an argument borrowed from the heretics of the Christians: you have a spirit you cannot see or touch, and so is Allah, in no one place rather than another. He took their answer instead of the Quran’s, and from it denied everything by which Allah described Himself."),
            .text("His doctrines, as the writers on the sects record them (al-Ash‘ari, Maqalat al-Islamiyyin; al-Baghdadi, al-Farq bayn al-Firaq; ash-Shahrastani, al-Milal wan-Nihal):"),
            .bullet("**No names and no attributes** for Allah in reality; whatever name He is given is a figure of speech."),
            .bullet("**The Quran is created**, and Allah did not speak to Musa."),
            .bullet("**Allah is in every place**, not above His Throne (adh-Dhahabi, Siyar 6/27)."),
            .bullet("**Faith is bare knowledge** of Allah in the heart, and disbelief bare ignorance of Him. The imams answered that Iblis and Pharaoh knew their Lord, and Waki‘, Ahmad, and Abu Ubayd declared this saying disbelief (Ibn Taymiyyah, Majmu‘ al-Fatawa 10/748–749)."),
            .bullet("**Compulsion (jabr)**: no one truly acts but Allah, and men’s deeds are ascribed to them only as a figure of speech."),
            .bullet("**Paradise and the Fire will perish** and come to an end."),
            .bullet("**Allah will not be seen** in the Hereafter."),
            .text("Ibn Taymiyyah summed him up: two innovations were famous from Jahm, the denial of the attributes, and extremism in the decree and in irja’ (Majmu‘ al-Fatawa 8/229). When al-Harith’s revolt was crushed in 128 AH, Jahm was taken prisoner and Salm ibn Ahwaz had him put to death (at-Tabari, Tarikh, events of 128 AH)."),
            .text("No sect drew harsher words from the Salaf. Al-Bukhari wrote:"),
            .quote(text: "“I looked into the words of the Jews, the Christians, and the Magians, and I saw none more astray in their disbelief than them; and I count as ignorant whoever does not declare them disbelievers, except one who does not know their disbelief” (al-Bukhari, Khalq Af‘al al-‘Ibad).", arabic: "نَظَرتُ فِي كَلَامِ اليَهُودِ وَالنَّصَارَى وَالمَجُوسِ فَمَا رَأَيتُ أَضَلَّ فِي كُفرِهِم مِنهُم، وَإِنِّي لَأَستَجهِلُ مَن لَا يُكَفِّرُهُم إِلَّا مَن لَا يَعرِفُ كُفرَهُم", dimmed: true),
            .text("Abdullah ibn al-Mubarak (may Allah have mercy on him) said:"),
            .quote(text: "“We allow ourselves to relate the words of the Jews and the Christians, but we do not allow ourselves to relate the words of the Jahmiyyah” (Abdullah ibn Ahmad, as-Sunnah 23).", arabic: "إِنَّا نَستَجِيزُ أَن نَحكِيَ كَلَامَ اليَهُودِ وَالنَّصَارَى، وَلَا نَستَجِيزُ أَن نَحكِيَ كَلَامَ الجَهمِيَّةِ", dimmed: true),
            .text("Asked to name the sects of this nation, he listed their four roots without the Jahmiyyah, and when the questioner asked why, he said, “You only asked me about the sects of the Muslims” (Ibn Battah, al-Ibanah al-Kubra 278). Uthman ibn Sa‘id ad-Darimi wrote that the Jahmiyyah are not counted among the people of the qiblah, and that they are declared disbelievers by nothing but a written Book, a narrated report, and a well-known disbelief (ar-Radd ‘ala al-Jahmiyyah 359). And al-Lalaka’i named five hundred and fifty or more of the Tabi‘un, their followers, and the imams, besides the Companions, who all said that the Quran is the speech of Allah, not created, and that whoever says it is created is a disbeliever (Sharh Usul I‘tiqad Ahl as-Sunnah 2/344)."),
            .text("Every later denial of the attributes is a portion of Jahm’s inheritance, which is why “Jahmi” became the Salaf’s word for anyone who denied the attributes or said the Quran was created, whatever he called himself. Ibn Taymiyyah observed that the men gathered against Imam Ahmad in the Mihnah were deniers of the attributes from every sect, whom Ibn al-Mubarak, Ahmad, Ishaq, and al-Bukhari all called Jahmiyyah, and that the Mu‘tazilah were only one kind of them (Majmu‘ al-Fatawa 8/229). But he did not put all of them in one rank:"),
            .quote(text: "“The Jahmiyyah are of three degrees. The worst are the extremists, who deny the names of Allah and His attributes … The second degree of Jahmism is the Jahmism of the Mu‘tazilah and those like them, who affirm the beautiful names of Allah in general but deny His attributes … The third degree is the Sifatiyyah, who affirm the attributes and oppose the Jahmiyyah, but in whom there is a kind of Jahmism … and these are nearer to the pure Sunnah than to the Jahmiyyah, the Rafidah, the Khawarij, and the Qadariyyah” (Ibn Taymiyyah, at-Tis‘iniyyah 1/265–271).", arabic: "وَكَذَلِكَ الجَهمِيَّةُ عَلَى ثَلَاثِ دَرَجَاتٍ: فَشَرُّهَا الغَالِيَةُ الَّذِينَ يَنفُونَ أَسمَاءَ اللَّهِ وَصِفَاتِهِ … وَالدَّرَجَةُ الثَّانِيَةُ مِنَ التَّجَهُّمِ: هُوَ تَجَهُّمُ المُعتَزِلَةِ وَنَحوِهِمُ الَّذِينَ يُقِرُّونَ بِأَسمَاءِ اللَّهِ الحُسنَى فِي الجُملَةِ لَكِن يَنفُونَ صِفَاتِهِ … وَأَمَّا الدَّرَجَةُ الثَّالِثَةُ: فَهُمُ الصِّفَاتِيَّةُ المُثبِتُونَ المُخَالِفُونَ لِلجَهمِيَّةِ، لَكِن فِيهِم نَوعٌ مِنَ التَّجَهُّمِ … وَهَؤُلَاءِ إِلَى أَهلِ السُّنَّةِ المَحضَةِ أَقرَبُ مِنهُم إِلَى الجَهمِيَّةِ وَالرَّافِضَةِ وَالخَوَارِجِ وَالقَدَرِيَّةِ", dimmed: true),
            .text("He placed Ibn Kullab and al-Ash‘ari’s school in the third degree. So it is wrong to call the Ash‘aris simply “Jahmiyyah”: they are nearer the Sunnah than the sects, though they carry something of Jahm’s inheritance, which is why the Salaf’s answers to Jahm still bear on what they reinterpret."),
        ]),
        ArticleSection("THE DOCTRINE AND THE PERSON", [
            .text("The Salaf judged doctrines by the texts, and some doctrines they called disbelief outright. But a ruling on a doctrine is not a ruling on every person who holds it: a specific person is declared a disbeliever only when the proof has reached him and his excuse, whether ignorance or a mistaken interpretation, has been removed, and that belongs to the scholars (see the Kufr page). Imam Ahmad is the clearest example, because the men of the Mihnah flogged him to make him say the very doctrine he called disbelief. Ibn Taymiyyah (may Allah have mercy on him) wrote:"),
            .quote(text: "“His texts are explicit in refusing to declare the Khawarij, the Qadariyyah, and others disbelievers; he declared disbelievers only the Jahmiyyah who deny the names and attributes of Allah … The declaring of the Jahmiyyah disbelievers is well known from the Salaf and the imams, but he did not declare their individuals disbelievers … And with this, Imam Ahmad asked Allah’s mercy and forgiveness for them, because he knew that it had not been made clear to them that they were belying the Messenger … but they interpreted and erred, and followed those who told them so” (Majmu‘ al-Fatawa 23/348–349).", arabic: "بَل نُصُوصُهُ صَرِيحَةٌ بِالِامتِنَاعِ مِن تَكفِيرِ الخَوَارِجِ وَالقَدَرِيَّةِ وَغَيرِهِم، وَإِنَّمَا كَانَ يُكَفِّرُ الجَهمِيَّةَ المُنكِرِينَ لِأَسمَاءِ اللَّهِ وَصِفَاتِهِ … وَتَكفِيرُ الجَهمِيَّةِ مَشهُورٌ عَنِ السَّلَفِ وَالأَئِمَّةِ، لَكِن مَا كَانَ يُكَفِّرُ أَعيَانَهُم … وَمَعَ هَذَا فَالإِمَامُ أَحمَدُ رَحِمَهُ اللَّهُ تَعَالَى تَرَحَّمَ عَلَيهِم وَاستَغفَرَ لَهُم، لِعِلمِهِ بِأَنَّهُم لَم يُبَيَّن لَهُم أَنَّهُم مُكَذِّبُونَ لِلرَّسُولِ … وَلَكِن تَأَوَّلُوا فَأَخطَئُوا وَقَلَّدُوا مَن قَالَ لَهُم ذَلِكَ", dimmed: true),
            .text("He prayed behind them and made dua for the caliph who had him flogged, which he could not have done had he thought them apostates (Majmu‘ al-Fatawa 12/488–489, 7/507–508). Ibn Taymiyyah held himself to the same rule with the scholars and judges of his own day who denied that Allah is above His Throne:"),
            .quote(text: "“That is why I used to say to the Jahmiyyah, the incarnationists and the deniers who denied that Allah the Exalted is above the Throne, when their persecution came: If I agreed with you I would be a disbeliever, because I know that what you say is disbelief; and you are not disbelievers in my view, because you are ignorant. And this was said to their scholars, their judges, their shaykhs, and their rulers” (Ibn Taymiyyah, al-Istighathah fi ar-Radd ‘ala al-Bakri, p. 253).", arabic: "وَلِهَذَا كُنتُ أَقُولُ لِلجَهمِيَّةِ مِنَ الحُلُولِيَّةِ وَالنُّفَاةِ الَّذِينَ نَفَوا أَن يَكُونَ اللَّهُ تَعَالَى فَوقَ العَرشِ لَمَّا وَقَعَت مِحنَتُهُم: أَنَا لَو وَافَقتُكُم كُنتُ كَافِرًا؛ لِأَنِّي أَعلَمُ أَنَّ قَولَكُم كُفرٌ، وَأَنتُم عِندِي لَا تَكفُرُونَ لِأَنَّكُم جُهَّالٌ، وَكَانَ هَذَا خِطَابًا لِعُلَمَائِهِم وَقُضَاتِهِم وَشُيُوخِهِم وَأُمَرَائِهِم", dimmed: true),
            .text("That is the balance: the doctrine is named for what it is, and the person is treated as a Muslim until the proof is established and the scholars rule otherwise. And the Ash‘aris and Maturidis are not in question here at all; as the Permanent Committee for Fatwa answered, “the Ash‘aris are not disbelievers; they only erred in their interpretation of some of the attributes” (Fatawa al-Lajnah ad-Da’imah 3/220, fatwa 6606)."),
        ]),
        ArticleSection("WHICH CREED IS CORRECT?", [
            .text("The creed of the Salaf, the Athari creed, is the correct one, and the reason is not that a scholar said so. It is that creed is known only through revelation:"),
            .ayah("53:3-4"),
            .text("And the people who received that revelation and lived with the one who brought it understood it best:"),
            .hadith("bukhari:2652", cite: "Sahih al-Bukhari 2652", arabic: 29...37, english: [4...23]),
            .ayah("9:100", words: 0...12),
            .text("The first three generations did not learn kalam, did not reinterpret the attributes, and did not say the Quran was created. Whatever creed they did not hold cannot be the creed of Islam, because Islam was complete in their time:"),
            .ayah("5:3", words: 39...49),
            .text("Shaykh al-Islam Ibn Taymiyyah (may Allah have mercy on him) put it in one sentence:"),
            .quote(text: "“There is no blame on the one who manifests the way of the Salaf, ascribes himself to it, and takes pride in it; rather it is obligatory to accept that from him by agreement, for the way of the Salaf can be nothing but the truth” (Majmu' al-Fatawa 4/149).", arabic: "لَا عَيبَ عَلَى مَن أَظهَرَ مَذهَبَ السَّلَفِ وَانتَسَبَ إِلَيهِ وَاعتَزَى إِلَيهِ، بَل يَجِبُ قَبُولُ ذَلِكَ مِنهُ بِالِاتِّفَاقِ، فَإِنَّ مَذهَبَ السَّلَفِ لَا يَكُونُ إِلَّا حَقًّا", dimmed: true),
            .text("This is said with fairness. Ash‘aris and Maturidis are Muslims of Ahl al-Qiblah whose scholars served the religion; the disagreement with them is over specific points of creed, argued with evidence and good manners, not with the enmity owed to the Mu‘tazilah or the Khawarij. And every Muslim, whatever label he inherited, is invited to the same thing: the Quran and the Sunnah as the Companions understood them."),
        ]),
        ArticleSection("COMMON QUESTIONS", [
            .markdown("**Where is Allah?**"),
            .text("Above His Throne, above the seven heavens, as He said of Himself, while His knowledge, hearing, and sight encompass everything. The Prophet (peace be upon him) asked the slave girl of Mu‘awiyah ibn al-Hakam:"),
            .hadith("muslim:537a", cite: "Sahih Muslim 537", arabic: 266...289, english: [354...386]),
            .text("He accepted “in the heaven” as the answer of a believer and made it the test of her faith. He said the same of himself when some complained about his division of gold:"),
            .hadith("bukhari:4351", cite: "Sahih al-Bukhari 4351", arabic: 91...102, english: [77...111]),
            .hadith("abudawud:4941", cite: "Sunan Abi Dawud 4941; graded sahih by al-Albani", arabic: 37...46, english: [4...35]),
            .text("The Quran says:"),
            .ayah("20:5"),
            .ayah("67:16"),
            .text("Zaynab bint Jahsh (may Allah be pleased with her) used to say to the other wives of the Prophet (peace be upon him):"),
            .hadith("bukhari:7420", cite: "Sahih al-Bukhari 7420", arabic: 62...70, english: [62...82]),
            .markdown("“In the heaven” means above it, as the Arabs say “in” for “upon” (Pharaoh threatened to crucify the magicians “on (fi) the trunks of palm trees,” Quran 20:71), and it does not mean that the heaven contains Him, for He is greater than everything He made. As for “He is with you wherever you are” (Quran 57:4), the same verse ties it to His knowing what enters the earth and what descends from the heaven, and the verse of the secret counsel is framed by His knowledge, opening “Have you not considered that Allah knows” and closing “Allah is, of all things, Knowing” (Quran 58:7), which is why the translators render it “with them [in knowledge].” So the Salaf explained it: ad-Dahhak said, “He is above the Throne and His knowledge is with them”; Sufyan ath-Thawri, asked about the verse, said, “His knowledge”; and Imam Ahmad answered the Jahmiyyah with the same (Abdullah ibn Ahmad, as-Sunnah; al-Lalaka’i, Sharh Usul I‘tiqad Ahl as-Sunnah; Ibn Abd al-Barr, at-Tamhid). Imam Malik’s answer about the rising is quoted above. Abu Hanifah (may Allah have mercy on him) said:"),
            .quote(text: "“Whoever says, ‘I do not know whether my Lord is in the heaven or on the earth,’ has disbelieved, because Allah says, ‘The Most Merciful [who is] above the Throne established,’ and His Throne is above His seven heavens” (Abu Hanifah, al-Fiqh al-Absat; cited by adh-Dhahabi in al-'Uluw).", arabic: "مَن قَالَ لَا أَعرِفُ رَبِّي فِي السَّمَاءِ أَو فِي الأَرضِ فَقَد كَفَرَ، لِأَنَّ اللَّهَ تَعَالَى يَقُولُ: الرَّحمَنُ عَلَى العَرشِ استَوَى، وَعَرشُهُ فَوقَ سَبعِ سَمَاوَاتٍ", dimmed: true),
            .text("Ibn Abd al-Barr the Maliki (d. 463 AH) wrote in at-Tamhid that the scholars of the Companions and the Tabi‘un, from whom the interpretation of the Quran is taken, said of the verse of the secret counsel: He is above the Throne and His knowledge is in every place. Adh-Dhahabi (d. 748 AH) gathered the statements of the Salaf on this in a book of its own, al-‘Uluw lil-‘Aliyy al-Ghaffar. The Jahmiyyah said “He is everywhere,” and the later kalam schools said “He is neither inside the world nor outside it, neither above nor below,” which, as the imams of the Sunnah answered, is a description of nothing."),
            .markdown("**Do we interpret Allah’s attributes?**"),
            .text("We affirm them with their meanings in Arabic and leave their “how” to Allah. The verse “There is nothing like unto Him, and He is the Hearing, the Seeing” (Quran 42:11), quoted above, negates likeness and affirms attributes in one breath, and Allah commands:"),
            .ayah("7:180", words: 0...9),
            .text("Deviation (ilhad) in His names includes denying them, likening them, and naming Him with what He did not name Himself. Al-Walid ibn Muslim asked al-Awza‘i, Malik, Sufyan ath-Thawri, and al-Layth ibn Sa‘d about the hadiths of the attributes, and they all said:"),
            .quote(text: "“Pass them on as they came, without asking how” (al-Lalaka'i, Sharh Usul I'tiqad Ahl as-Sunnah; adh-Dhahabi, al-'Uluw).", arabic: "أَمِرُّوهَا كَمَا جَاءَت بِلَا كَيفٍ", dimmed: true),
            .text("“As they came” means with their meaning; a text has nothing to pass on if its meaning is unknown. When Allah says He has mercy, we know what mercy is in the language and we do not know how His mercy is; when He says He rose over the Throne, the rising is known and the “how” is not, exactly as Malik said. What Ahl as-Sunnah refuse is ta’wil in the later sense: turning a word from its plain meaning to another because of a rational objection, such as making the Hand “power,” the Face “the Self,” and the rising “conquest.” Ibn Kathir (may Allah have mercy on him), a Shafi‘i, set out the rule at the verse of the Throne:"),
            .quote(text: "“In this matter, the way to follow is that of the righteous Salaf: Malik, al-Awza‘i, ath-Thawri, al-Layth ibn Sa‘d, ash-Shafi‘i, Ahmad, Ishaq ibn Rahawayh, and the other imams of the Muslims, early and late, which is to pass the texts on as they came, without asking how, without likening, and without denial” (Ibn Kathir, Tafsir, at Quran 7:54).", arabic: "وَإِنَّمَا يُسلَكُ فِي هَذَا المَقَامِ مَذهَبَ السَّلَفِ الصَّالِحِ: مَالِكٍ وَالأَوزَاعِيِّ وَالثَّورِيِّ وَاللَّيثِ بنِ سَعدٍ وَالشَّافِعِيِّ وَأَحمَدَ وَإِسحَاقَ بنِ رَاهَوَيهِ وَغَيرِهِم مِن أَئِمَّةِ المُسلِمِينَ قَدِيمًا وَحَدِيثًا، وَهُوَ إِمرَارُهَا كَمَا جَاءَت مِن غَيرِ تَكيِيفٍ وَلَا تَشبِيهٍ وَلَا تَعطِيلٍ", dimmed: true),
            .text("The one who follows what is unclear in pursuit of an interpretation is the one the Prophet (peace be upon him) warned against (Quran 3:7 and Sahih al-Bukhari 4547, above). And every imam Ibn Kathir named died before the Ash‘ari and Maturidi schools existed: the way of the Salaf is not a later party’s position but the oldest position there is."),
            .markdown("**Is the Quran the created or the uncreated speech of Allah?**"),
            .text("The Quran is the speech of Allah, revealed, not created; it came from Him and to Him it will return. Speech is an attribute of the Speaker, and an attribute of Allah is not a creature. Allah calls the Quran His own words:"),
            .ayah("9:6", words: 0...9),
            .ayah("48:15", words: 9...13),
            .text("The Prophet (peace be upon him) taught us to say:"),
            .hadith("muslim:2708a", cite: "Sahih Muslim 2708", arabic: 63...70, english: [16...32]),
            .text("Refuge is sought only in Allah and His attributes, never in a created thing, and the Salaf used this very hadith against the Jahmiyyah. The doctrine that the Quran is created came from al-Ja‘d ibn Dirham and Jahm, was adopted by the Mu‘tazilah, and was imposed by force in the Mihnah; Imam Ahmad’s stand is told above. Abu Hanifah (may Allah have mercy on him), a contemporary of Jahm who refuted his followers, had written more than half a century before the Mihnah:"),
            .quote(text: "“The Quran is the speech of Allah the Exalted: written in the mushafs, preserved in the hearts, recited on the tongues, sent down upon the Prophet … and the Quran is not created” (Abu Hanifah, al-Fiqh al-Akbar).", arabic: "وَالقُرآنُ كَلَامُ اللَّهِ تَعَالَى، فِي المَصَاحِفِ مَكتُوبٌ، وَفِي القُلُوبِ مَحفُوظٌ، وَعَلَى الأَلسُنِ مَقرُوءٌ، وَعَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيهِ وَسَلَّمَ مُنَزَّلٌ … وَالقُرآنُ غَيرُ مَخلُوقٍ", dimmed: true),
            .text("Al-Bukhari wrote a whole book on the matter, Khalq Af‘al al-‘Ibad, “The Creation of the Servants’ Actions”: the Quran is uncreated, while our reciting, writing, and voices are our own created actions. At-Tahawi stated in his creed that the Quran is the speech of Allah that came from Him as speech without a “how,” that it is not the speech of any created being, and that whoever hears it and claims it is human speech has disbelieved. The later Ash‘ari position, that Allah’s speech is one eternal inner meaning while the recited Quran is a created expression of it, is a compromise the Salaf did not know: what is between the two covers of the mushaf is the speech of Allah."),
            .markdown("**Will the believers see Allah?**"),
            .text("Yes, in the Hereafter, with their eyes, without encompassing Him. The Quran says:"),
            .ayah("75:22-23"),
            .ayah("10:26", words: 1...4),
            .text("The Prophet (peace be upon him) explained the “extra” in this verse:"),
            .hadith("muslim:181a", cite: "Sahih Muslim 181", arabic: 37...77, english: [0...77]),
            .text("Jarir ibn Abdillah (may Allah be pleased with him) said the Prophet (peace be upon him) looked at the full moon and said:"),
            .hadith("bukhari:554", cite: "Sahih al-Bukhari 554, Sahih Muslim 633", arabic: 32...42, english: [15...34]),
            .text("Ash-Shafi‘i (may Allah have mercy on him) drew the same proof from the opposite verse:"),
            .ayah("83:15"),
            .text("He said that since the disbelievers are veiled from Him in His anger, His friends will see Him in His pleasure (related by al-Lalaka’i, and by Ibn Kathir at this verse). The Mu‘tazilah denied the seeing and set “Vision perceives Him not” (Quran 6:103) against it, but perceiving (idrak) is encompassing, not seeing: the believers will see Him and never encompass Him, just as they know Him and never encompass His knowledge. The Ash‘aris affirm the seeing, and Ahl as-Sunnah agree with them in affirming it, though not in their claim that He is seen in no direction; Ibn Abi al-‘Izz said whoever holds that should re-examine his reason (Sharh al-‘Aqidah at-Tahawiyyah)."),
            .markdown("**Is the Muslim who commits a major sin a believer or a disbeliever?**"),
            .text("A believer with deficient faith: a believer by his faith and a sinner (fasiq) by his major sin. He is not expelled from Islam, and in the Hereafter he is under Allah’s will, forgiven or punished and then brought out of the Fire by the tawhid (تَوحِيد, from the root و-ح-د: singling Allah out in everything that belongs to Him alone) he died upon. Three sects went wrong here: the Khawarij said he is a disbeliever, the Mu‘tazilah said he is in a station between the two, and the Murji’ah said his faith is untouched. Allah says:"),
            .ayah("4:48", words: 0...12),
            .ayah("49:9", words: 0...6),
            .ayah("49:10", words: 0...2),
            .text("Allah calls fighting Muslims “believers” and “brothers” while their sin is at its height. The Prophet (peace be upon him) said to Abu Dharr:"),
            .hadith("bukhari:5827", cite: "Sahih al-Bukhari 5827", arabic: 50...76, english: [31...81]),
            .text("When he took the pledge of the Companions not to associate anything with Allah, not to steal, not to commit adultery, and not to kill their children, he said:"),
            .hadith("bukhari:18", cite: "Sahih al-Bukhari 18", arabic: 74...108, english: [99...166]),
            .text("A sinner whose matter is “with Allah, if He wills He pardons him” is not a disbeliever, for the disbeliever is not pardoned. And when a man cursed a Companion who had been flogged more than once for drinking, he said:"),
            .hadith("bukhari:6780", cite: "Sahih al-Bukhari 6780", arabic: 85...93, english: [81...96]),
            .text("A drinker who loves Allah and His Messenger is a believer with a sin, not a disbeliever. That faith rises and falls is stated in the Quran:"),
            .ayah("48:4", words: 0...10),
            .ayah("8:2", words: 8...13),
            .text("So sins lower faith without ending it, and repentance and good deeds raise it again; this is al-Bukhari’s “it increases and decreases” quoted in the Key Terms. The Companions, and the Ahlul Bayt with them, never made takfir of a Muslim for a sin, and Ali fought the Khawarij once their takfir turned into shedding Muslim blood."),
            .markdown("**Do we believe in the decree while having free will?**"),
            .text("Yes, both at once, because Allah affirmed both at once. Belief in the decree has four levels: Allah knew everything before it was; He wrote it; nothing happens except by His will; and He created everything, including the servants’ acts."),
            .ayah("57:22", words: 0...15),
            .ayah("37:96"),
            .text("And in the same Quran the servant’s will is real, and it is the ground of his reward:"),
            .ayah("81:28-29"),
            .ayah("76:3"),
            .text("The verses of at-Takwir put the two together in a single breath: a will of yours, inside the will of Allah. The Prophet (peace be upon him) said:"),
            .hadith("muslim:2653b", cite: "Sahih Muslim 2653", arabic: 43...60, english: [7...32]),
            .text("When the Companions asked whether they should then rely on what is written and give up deeds, he answered:"),
            .hadith("bukhari:4949", cite: "Sahih al-Bukhari 4949, Sahih Muslim 2647", arabic: 67...72, english: [65...92]),
            .text("That is the whole answer: the decree is not a reason to stop; it is the unseen behind your striving, and you are addressed by the command, not by the hidden book. When Umar (may Allah be pleased with him) turned back from a land struck by plague and Abu Ubaydah asked whether he was fleeing from the decree of Allah, he said:"),
            .hadith("bukhari:5729", cite: "Sahih al-Bukhari 5729", arabic: 188...195, english: [264...277]),
            .text("Choosing a course is itself part of what Allah decreed. Ibn Umar’s disavowal of the Qadariyyah is quoted above (Sahih Muslim 8). The Qadariyyah denied the decree to protect man’s freedom, the Jabriyyah (الجَبرِيَّة, from ج-ب-ر, compulsion) denied man’s freedom to protect the decree, and Ahl as-Sunnah accept both sets of texts; Ibn al-Qayyim (may Allah have mercy on him) wrote Shifa’ al-‘Alil on nothing else."),
            .markdown("**Are the Ash‘aris and Maturidis disbelievers?**"),
            .text("No. They are Muslims of Ahl al-Qiblah who bear witness to the two testimonies, pray our prayer, and love the Prophet and his Companions. The Prophet (peace be upon him) said:"),
            .hadith("bukhari:391", cite: "Sahih al-Bukhari 391", arabic: 31...50, english: [4...40]),
            .text("His warning that a charge of disbelief thrown at a brother returns upon one of the two (Sahih al-Bukhari 6103, quoted above) applies here with full force. Their scholars, an-Nawawi, Ibn Hajar, al-Qurtubi, al-Bayhaqi, and many more, served the Sunnah, and every Muslim is in their debt. Ibn Taymiyyah (may Allah have mercy on him), who debated the Ash‘aris more than anyone, called them the nearest of the theologians to the Sunnah; Ibn Baz said plainly that they are not disbelievers; and the Permanent Committee gave the same answer. Their words are quoted above under The Schools and Where They Stand and The Doctrine and the Person. The disagreement with them is real, in the attributes, in the definition of faith, in the speech of Allah, and in the place of reason, and it is argued in the manner set out under Which Creed Is Correct above."),
            .markdown("**Can I follow a fiqh madhhab (Hanafi, Maliki, Shafi‘i, Hanbali) and hold the Athari creed?**"),
            .text("Yes, and that is exactly what the four imams did. Their fiqh differed; their creed was one, and it was the creed of the Salaf. Abu Hanifah’s statements on the Quran and on Allah being above His Throne are quoted above (al-Fiqh al-Akbar, al-Fiqh al-Absat), and at-Tahawi, a Hanafi, opened his creed by calling it the creed of Abu Hanifah and his two companions. Malik’s answer on the rising is the motto of the whole creed. Ash-Shafi‘i (may Allah have mercy on him) said:"),
            .quote(text: "“I believe in Allah and in what came from Allah as Allah intended, and I believe in the Messenger of Allah and in what came from the Messenger of Allah as the Messenger of Allah intended” (Ibn Qudamah, Lum'at al-I'tiqad).", arabic: "آمَنتُ بِاللَّهِ وَبِمَا جَاءَ عَنِ اللَّهِ عَلَى مُرَادِ اللَّهِ، وَآمَنتُ بِرَسُولِ اللَّهِ وَبِمَا جَاءَ عَن رَسُولِ اللَّهِ عَلَى مُرَادِ رَسُولِ اللَّهِ", dimmed: true),
            .text("Ahmad is its imam. The great scholars of every madhhab after them held the same: Ibn Abd al-Barr the Maliki (at-Tamhid), Ibn Kathir and adh-Dhahabi the Shafi‘is, Ibn Qudamah and Ibn Rajab the Hanbalis, and in recent times Ibn Baz and Ibn al-Uthaymin, Hanbalis in fiqh, and al-Albani, who followed the evidence without binding himself to a madhhab. Following a madhhab in fiqh is following a qualified scholar where the texts admit more than one understanding; following the Salaf in creed is following the Prophet and his Companions where they admit only one. There is no tension between the two. The tension people feel comes only from the fact that two of the kalam schools grew up inside two of the fiqh schools and came to be confused with them."),
            .markdown("**Did the Companions or the Ahlul Bayt hold a different creed?**"),
            .text("No. Ali (may Allah be pleased with him) was asked by his son Muhammad ibn al-Hanafiyyah who the best of people was after the Messenger of Allah, and he said:"),
            .hadith("bukhari:3671", cite: "Sahih al-Bukhari 3671", arabic: 31...53, english: [19...49]),
            .text("This ranking, Abu Bakr then Umar, is the creed of Ahl as-Sunnah on the tongue of Ali himself, taught to his own son. He named three of his sons Abu Bakr, Umar, and Uthman, as the biographers of both sides record (Ibn Sa‘d, at-Tabaqat al-Kubra; Ibn Taymiyyah, Minhaj as-Sunnah; the Shia scholar al-Mufid, al-Irshad), and he gave his daughter Umm Kulthum, the Prophet’s granddaughter, in marriage to Umar. Al-Bukhari relates that when Umar was distributing garments, someone said to him:"),
            .hadith("bukhari:2881", cite: "Sahih al-Bukhari 2881", arabic: 39...57, english: [23...48]),
            .text("The Arabs call a granddaughter a daughter, and the Prophet’s granddaughter was in Umar’s house as his wife. Al-Hasan ibn Ali gave up the caliphate to Mu‘awiyah to spare Muslim blood, fulfilling what the Prophet (peace be upon him) had foretold of him (Sahih al-Bukhari 2704). Ja‘far as-Sadiq, the great-great-grandson of Ali, whose mother descended from Abu Bakr on both sides, used to say:"),
            .quote(text: "“Abu Bakr begot me twice” (adh-Dhahabi, Siyar A'lam an-Nubala').", arabic: "وَلَدَنِي أَبُو بَكرٍ مَرَّتَينِ", dimmed: true),
            .text("And Zayd ibn Ali refused to disavow Abu Bakr and Umar even when it cost him his army, as told under Rafidah below. The Ahlul Bayt held the creed of the Companions because they were Companions and the children of Companions; the claim that they hid another religion behind taqiyyah is a charge against their honesty, and Ahl as-Sunnah defend their honesty."),
            .markdown("**Is it enough to say “I follow the Quran and Sunnah” without the understanding of the Salaf?**"),
            .text("No, because the Khawarij said the same. They recited the Quran, and the Prophet (peace be upon him) said it did not pass their throats (Sahih al-Bukhari 3610, above); al-Bukhari relates that Ibn Umar counted them the worst of Allah’s creation because they took verses revealed about the disbelievers and applied them to the believers. Every sect quotes the Quran; what separates truth from error is the understanding with which it is read, and Allah bound the believer to the understanding of the first believers:"),
            .ayah("4:115"),
            .text("“The way of the believers” when this verse came down was the way of the Companions, and Allah made following it a condition of safety alongside obeying the Messenger. He praised those who follow the Muhajirun and the Ansar “with good conduct” (Quran 9:100, above), the Prophet (peace be upon him) called his generation the best of people (Sahih al-Bukhari 2652, above), and for the time of disagreement he commanded:"),
            .hadith("abudawud:4607", cite: "Sunan Abi Dawud 4607; graded sahih by al-Albani", arabic: 104...132, english: [147...192]),
            .text("He did not say “my Sunnah alone”; he joined to it the Sunnah of the caliphs, because their understanding of his Sunnah is part of it. Ibn Mas‘ud (may Allah be pleased with him) said:"),
            .quote(text: "“Allah looked into the hearts of His servants and found the heart of Muhammad the best of their hearts, so He chose him for Himself and sent him with His message. Then He looked into the hearts of His servants after the heart of Muhammad and found the hearts of his Companions the best of their hearts, so He made them the ministers of His Prophet, fighting for His religion” (Musnad Ahmad 3600; its chain graded hasan by Shu'ayb al-Arna'ut).", arabic: "إِنَّ اللَّهَ نَظَرَ فِي قُلُوبِ العِبَادِ فَوَجَدَ قَلبَ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيهِ وَسَلَّمَ خَيرَ قُلُوبِ العِبَادِ، فَاصطَفَاهُ لِنَفسِهِ، فَابتَعَثَهُ بِرِسَالَتِهِ، ثُمَّ نَظَرَ فِي قُلُوبِ العِبَادِ بَعدَ قَلبِ مُحَمَّدٍ، فَوَجَدَ قُلُوبَ أَصحَابِهِ خَيرَ قُلُوبِ العِبَادِ، فَجَعَلَهُم وُزَرَاءَ نَبِيِّهِ، يُقَاتِلُونَ عَلَى دِينِهِ", dimmed: true),
            .text("Imam Ahmad’s Usul as-Sunnah, quoted above, begins with the same rule: holding to what the Companions were upon. “Quran and Sunnah” is the right slogan; “as the Companions understood them” is what makes it true."),
            .markdown("**Is a single-chain (ahad) hadith proof in creed?**"),
            .text("Yes. An authentic hadith is proof in creed exactly as it is proof in law; the division between “proof for rulings” and “not proof for beliefs” was invented by the kalam schools, and the Companions did not know it. The Prophet (peace be upon him) sent Mu‘adh alone to Yemen to teach the people the creed itself:"),
            .hadith("bukhari:1395", cite: "Sahih al-Bukhari 1395, Sahih Muslim 19", arabic: 46...72, english: [9...56]),
            .text("In another wording, “let the first thing you call them to be that they single out Allah” (Sahih al-Bukhari 7372). If the report of one trustworthy man did not establish belief, sending one man to teach it would have been pointless. When the qiblah was changed, one man carried the news to Quba:"),
            .hadith("bukhari:403", cite: "Sahih al-Bukhari 403", arabic: 21...55, english: [0...58]),
            .text("They turned in the middle of the prayer on the word of one man, and the Prophet (peace be upon him) did not censure them; a single report changed the direction of worship. He prayed for the single transmitter and made him a carrier of the religion:"),
            .hadith("abudawud:3660", cite: "Sunan Abi Dawud 3660; graded sahih by al-Albani", arabic: 39...47, english: [8...28]),
            .text("Allah commanded that a group from every division go out to learn and then warn their people:"),
            .ayah("9:122", words: 6...20),
            .ayah("49:6", words: 0...7),
            .text("Warning by a few implies that the few are to be believed, and the command to verify the report of a disobedient man implies that the report of a trustworthy man is accepted as it is. Ash-Shafi‘i argued the point at length in ar-Risalah, Ibn Abd al-Barr in at-Tamhid, and Ibn al-Qayyim in as-Sawa‘iq al-Mursalah: the rule of the Salaf is that a sahih hadith gives knowledge and is acted upon in all things, creed included."),
            .markdown("**Is the “three categories of tawhid” a bid‘ah?**"),
            .text("No. A bid‘ah (بِدعَة, from ب-د-ع, to originate something with no precedent) is a new act of worship; a classification is a way of teaching what the texts contain, like “the five pillars of Islam,” “the six pillars of faith,” or the division of fiqh into worship and dealings. Allah Himself distinguishes the tawhid the idolaters affirmed from the tawhid they refused:"),
            .ayah("31:25", words: 0...7),
            .ayah("39:3", words: 9...15),
            .text("The Makkan idolaters affirmed that Allah alone creates, provides, and controls (Quran 10:31, 43:87), which is tawhid ar-rububiyyah, and they were still mushrikin, because they worshipped others “to bring us nearer to Allah,” which is a breach of tawhid al-uluhiyyah. The Prophet (peace be upon him) was not sent to teach them that Allah exists; he was sent so that they would worship Him alone, and he sent Mu‘adh to call the People of the Book first “to single out Allah” (Sahih al-Bukhari 7372). The distinction is therefore in the Quran itself; the terms only name it, as Surah Maryam 19:65 names all three in one verse (see Key Terms). Nor is the classification new: Ibn Battah al-‘Ukbari (d. 387 AH) set out the three in al-Ibanah, saying that the foundation of faith in Allah is to believe in His rububiyyah, in His wahdaniyyah in worship, and in His attributes; Ibn al-Qayyim in Madarij as-Salikin and Ibn Abi al-‘Izz al-Hanafi (d. 792 AH) in his commentary on at-Tahawiyyah explained that the tawhid the messengers brought is of two kinds, of knowledge and affirmation, and of intent and seeking, which are the same three headings folded into two; and Ibn Taymiyyah used the division throughout his works. Whoever objects to the classification while affirming everything in it disagrees over a word, not over creed."),
            .markdown("**Why does the correct creed matter if I pray and fast?**"),
            .text("Because deeds are accepted on the basis of creed, not the other way round. Allah says:"),
            .ayah("39:65", words: 7...10),
            .ayah("18:103-105"),
            .text("Ibn Umar swore that a man who spent a mountain of gold would have nothing accepted from him until he believed in the decree (Sahih Muslim 8, above), and the Prophet (peace be upon him) described the Khawarij, beside whose prayer and fasting you would belittle your own, as passing out of the religion (Sahih al-Bukhari 3610, above). Prayer and fasting are the branches and creed is the root, and a tree with a rotten root bears nothing however green it looks. That is why the Prophet (peace be upon him) spent the Makkan years teaching tawhid before the five prayers were made obligatory, why he sent Mu‘adh to teach the testimony before the prayer and the zakah, and why Allah says:"),
            .ayah("5:27", words: 20...24),
            .text("None of this means that a Muslim who has never studied the terms is lost; most Muslims hold the creed of the Salaf by instinct, believing that Allah is above, that the Quran is His word, and that they will see Him, without knowing the names of the sects that denied it. Learning the creed protects that instinct from the doubts of the sects and the slogans of the Khawarij. And a right creed is not a licence to abandon the deeds: faith is belief, statement, and action, and the one who has learned the truth about Allah has the most reason of all to pray and fast."),
        ]),
        ArticleSection("IN SUMMARY", [
            .text("Aqeedah is the knot in the heart, and it is one: the creed of all the prophets, held by every Companion and the Ahlul Bayt alike. The Salaf preserved it as the Athari creed, the only correct one, and Imam Ahmad defended it under torture. The Ash‘aris and Maturidis came three centuries later and erred in parts of it while remaining Muslims; the Jahmiyyah and the first Qadariyyah denied what the Salaf counted as the heart of faith; and even then the Salaf named the doctrine for what it was before they would ever name a person."),
        ]),
        ArticleSection("KEY TERMS", [
            .markdown("**Aqeedah (عَقِيدَة) and i‘tiqad (اِعتِقَاد)**: aqeedah, from the root ع-ق-د explained above, is the belief itself; i‘tiqad is the verbal noun of i‘taqada, “to hold firmly,” the act of holding it, which is why the classic books carry names like Sharh Usul I‘tiqad Ahl as-Sunnah of al-Lalaka’i (d. 418 AH) and Lum‘at al-I‘tiqad of Ibn Qudamah (d. 620 AH). Nobody founded aqeedah; it is the scholars’ word for what the Quran and Sunnah call iman, and its content was fixed by revelation before any school existed."),
            .markdown("**Iman (إِيمَان)**: from the root **أ-م-ن**, which carries both **amn**, security, and **tasdiq**, affirming something as true; the brothers of Yusuf used the same verb when they said “you would not believe us” (Quran 12:17). In the Shari‘ah, iman is belief in the heart, statement on the tongue, and action of the limbs; it increases by obedience and decreases by sin. Al-Bukhari opened the Book of Faith in his Sahih with exactly this definition:"),
            .quote(text: "“It is statement and action, and it increases and decreases” (Sahih al-Bukhari, Kitab al-Iman, opening chapter).", arabic: "وَهُوَ قَولٌ وَفِعلٌ، وَيَزِيدُ وَيَنقُصُ", dimmed: true),
            .text("Its six pillars are the ones the Prophet (peace be upon him) listed for Jibril in the hadith quoted above (Sahih Muslim 8): belief in Allah, His angels, His books, His messengers, the Last Day, and the decree. The Quran gathers the first five in one verse and names the sixth in another:"),
            .ayah("2:177", words: 9...18),
            .ayah("54:49"),
            .text("Deeds belong to faith, which is why the Prophet (peace be upon him) counted modesty among its branches:"),
            .hadith("bukhari:9", cite: "Sahih al-Bukhari 9", arabic: 40...47, english: [4...45]),
            .markdown("**Tawhid (تَوحِيد)**: the verbal noun of wahhada, “to make one” or “to single out,” from the root **و-ح-د**: to single Allah out in everything that belongs to Him alone. It is the Prophet’s own word: sending Mu‘adh to Yemen he said, “let the first thing you call them to be that they single out Allah (yuwahhidu Allah)” (Sahih al-Bukhari 7372). The scholars describe what the Quran contains under three headings: **tawhid ar-rububiyyah (تَوحِيد الرُّبُوبِيَّة)**, Allah alone creates, owns, provides, and controls; **tawhid al-uluhiyyah (تَوحِيد الأُلُوهِيَّة)**, Allah alone is worshipped; and **tawhid al-asma’ was-sifat (تَوحِيد الأَسمَاء وَالصِّفَات)**, His names and attributes are affirmed as He affirmed them, without likeness. This is not a new creed but a description, just as “the five pillars of Islam” is a description of what the Prophet (peace be upon him) said (Sahih al-Bukhari 8). One verse carries all three:"),
            .ayah("19:65"),
            .text("“Lord of the heavens and the earth” is rububiyyah, “so worship Him” is uluhiyyah, and “Do you know of any similarity to Him?” is the names and attributes. Surah al-Ikhlas does the same in four verses:"),
            .ayah("112:1-4"),
            .markdown("**Athar (أَثَر), Athari, Ahl al-Athar, Ahl al-Hadith**: athar, from the root **أ-ث-ر**, is a track or a trace, what someone leaves behind; Allah says He records “what they have put forth and what they left behind (atharahum)” (Quran 36:12). A narration is an athar because it is the trace the Prophet (peace be upon him) and his Companions left. So the creed is named after narration, not after any man, and its people are **Ahl al-Athar (أَهل الأَثَر)** and **Ahl al-Hadith (أَهل الحَدِيث)**; its imam is Ahmad ibn Hanbal, as its own section above explains. The Prophet (peace be upon him) said:"),
            .hadith("bukhari:3641", cite: "Sahih al-Bukhari 3641, Sahih Muslim 1920", arabic: 26...47, english: [6...53]),
            .text("Imam Ahmad (may Allah have mercy on him) said of this group:"),
            .quote(text: "“If this victorious group is not the people of hadith, then I do not know who they are” (al-Hakim, Ma'rifat Ulum al-Hadith, with a chain Ibn Hajar graded sahih; al-Khatib al-Baghdadi, Sharaf Ashab al-Hadith; an-Nawawi, Sharh Sahih Muslim 13/67).", arabic: "إِن لَم تَكُن هَذِهِ الطَّائِفَةُ المَنصُورَةُ أَصحَابَ الحَدِيثِ فَلَا أَدرِي مَن هُم", dimmed: true),
            .markdown("**Kalam (كَلَام) and the mutakallimun (المُتَكَلِّمُون)**: kalam means “speech.” **‘Ilm al-kalam** is theology argued by speech, that is, by rational premises and disputation, instead of received by narration, and the mutakallimun are its practitioners. Its first practitioners in Islam were the Mu‘tazilah; the Ash‘ari and Maturidi schools later took up its tools in order to answer them. The Salaf condemned it by name: ash-Shafi‘i’s verdict is quoted above under Two Roads, and Imam Ahmad said that a man of kalam never prospers, and that you hardly see anyone look into kalam without corruption entering his heart (Ibn Abd al-Barr, Jami‘ Bayan al-‘Ilm wa-Fadlih)."),
            .markdown("**Ahl as-Sunnah wal-Jama‘ah (أَهل السُّنَّة وَالجَمَاعَة)**: the Sunnah, from **س-ن-ن**, is a laid-down path, the way of the Prophet (peace be upon him); the Jama‘ah, from **ج-م-ع**, “to gather,” is the united body of the Companions and whoever holds to their way. The name is not a party label: the Jama‘ah is the Prophet’s own name for the saved group (the hadith below), and the Sunnah is what he commanded to be held fast to (Sunan Abi Dawud 4607; graded sahih by al-Albani; quoted above in Common Questions). Having said that this nation would split into seventy-three sects, he said (where the translation reads “the majority group,” the Arabic is al-jama‘ah, the Jama‘ah):"),
            .hadith("abudawud:4597", cite: "Sunan Abi Dawud 4597; graded hasan by al-Albani", arabic: 75...83, english: [43...64]),
            .text("Ibn Mas‘ud (may Allah be pleased with him) explained that the Jama‘ah is whatever agrees with the truth, even if you are alone (al-Lalaka’i, Sharh Usul I‘tiqad Ahl as-Sunnah). And Ibn Abbas (may Allah be pleased with them both) is related to have used the very phrase in explaining the verse:"),
            .ayah("3:106", words: 0...4),
            .text("Ibn Kathir (may Allah have mercy on him) relates it from him in his Tafsir at this verse: the faces of Ahl as-Sunnah wal-Jama‘ah will turn white, and the faces of the people of innovation and division will turn black."),
            .markdown("**Salaf (سَلَف) and Khalaf (خَلَف)**: salaf, from **س-ل-ف**, is what has gone before; Allah says of a destroyed people, “We made them a precedent (salafan)” (Quran 43:56). In creed, the Salaf are the first three generations, the Companions, the Tabi‘un, and their followers, whom the Prophet (peace be upon him) called the best of people (Sahih al-Bukhari 2652, quoted above). Khalaf, from **خ-ل-ف**, is what comes after; the Quran speaks of “successors (khalf)” who inherited the Scripture and neglected it (Quran 7:169). In the books of creed the Khalaf are the later scholars who took up kalam and reinterpretation. A saying spread among them, “the way of the Salaf is safer, the way of the Khalaf is more knowledgeable and wiser,” and Ibn Taymiyyah (may Allah have mercy on him) answered in al-Fatwa al-Hamawiyyah that the way of the Salaf is safer, more knowledgeable, and wiser all at once, because it is the way of the people who understood revelation best."),
            .markdown("**Mu‘tazilah (المُعتَزِلَة)**: from **ع-ز-ل**, i‘tazala, “to withdraw” or “to set oneself apart.” Wasil ibn Ata (80–131 AH) sat in the circle of al-Hasan al-Basri (d. 110 AH) in Basrah. When a man asked about the Muslim who commits a major sin, Wasil answered ahead of his teacher that he is neither a believer nor a disbeliever but in “a station between the two stations,” and withdrew to a pillar of the mosque with those who agreed with him; al-Hasan said, “Wasil has withdrawn from us (i‘tazalana Wasil)” (ash-Shahrastani, al-Milal wan-Nihal). His companion Amr ibn Ubayd (d. 144 AH) joined him, and the name stuck. They built their creed on five principles (al-usul al-khamsah): **tawhid**, by which they meant that Allah is knowing and powerful by His essence with no attributes additional to it, which Ahl as-Sunnah call a denial of the attributes; **‘adl**, “justice,” by which they meant that Allah does not create the servants’ acts; **al-wa‘d wal-wa‘id**, the promise and the threat, by which they meant that the major sinner is in the Fire forever; **al-manzilah bayn al-manzilatayn**, the station between two stations; and **enjoining good and forbidding evil**, by which they justified revolt against the rulers. They called themselves “the people of tawhid and justice”; Ahl as-Sunnah called them the Mu‘tazilah and, for their denial of the decree, the Qadariyyah (al-Ash‘ari, Maqalat al-Islamiyyin; ash-Shahrastani, al-Milal wan-Nihal)."),
            .markdown("**Ash‘ariyyah (الأَشعَرِيَّة)**: named after Abu al-Hasan Ali ibn Isma‘il al-Ash‘ari (260–324 AH), not after the Companion Abu Musa al-Ash‘ari (may Allah be pleased with him), his ancestor. He was a Mu‘tazili for about forty years under his stepfather al-Jubba’i, renounced them publicly in the mosque of Basrah, and ended by writing al-Ibanah on the creed of Imam Ahmad, as quoted above (Ibn Asakir, Tabyin Kadhib al-Muftari). The school that bears his name follows his middle period rather than his last book: it affirms seven attributes (life, knowledge, power, will, hearing, sight, and speech) by rational proof, reinterprets (**ta’wil**) or consigns the meaning of (**tafwid**) the rest, such as the Hand, the Face, and the rising over the Throne, and proves the existence of Allah by the kalam argument from the origination of bodies rather than by the way of the Quran."),
            .markdown("**Maturidiyyah (المَاتُرِيدِيَّة)**: named after Abu Mansur Muhammad ibn Muhammad al-Maturidi (d. 333 AH) of Maturid, a quarter of Samarqand, a Hanafi jurist and the author of Kitab at-Tawhid and Ta’wilat al-Quran; the school is described above under The Schools of Kalam, and its differences with the Ash‘aris under Ash‘aris and Maturidis: How They Differ."),
            .markdown("**Khawarij (الخَوَارِج), Haruriyyah (الحَرُورِيَّة), al-Muhakkimah (المُحَكِّمَة)**: three names for one sect. Khawarij is from kharaja, “to go out”: they went out against Ali (may Allah be pleased with him), and in the Prophet’s words, quoted above under The Rejected Sects, they “pass out” of the religion. Haruriyyah is from Harura’, the village near Kufah where they first gathered after Siffin; the name was already current among the Companions, for when a woman asked Aisha (may Allah be pleased with her) whether a menstruating woman makes up her prayers, she replied:"),
            .hadith("bukhari:321", cite: "Sahih al-Bukhari 321", arabic: 23...35, english: [20...53]),
            .text("Al-Muhakkimah is from their slogan “no judgement (hukm) but Allah’s,” with which they rejected the arbitration (tahkim) between Ali and Mu‘awiyah; Ali’s reply to it is quoted above. Ali fought them at Nahrawan in 38 AH, and one of the Khawarij, Abd ar-Rahman ibn Muljam, struck him down in Kufah in Ramadan 40 AH (Ibn Kathir, al-Bidayah wan-Nihayah; ash-Shahrastani, al-Milal wan-Nihal)."),
            .markdown("**Jahmiyyah (الجَهمِيَّة)**: the followers of Jahm ibn Safwan (executed 128 AH), who took his teaching from al-Ja‘d ibn Dirham: the deniers of Allah’s names and attributes, and in the Salaf’s usage anyone who denied the attributes or said the Quran was created, whatever he called himself. Their history, their doctrines, and the Salaf’s verdict are set out above under The Jahmiyyah."),
            .markdown("**Murji’ah (المُرجِئَة)**: from **ر-ج-أ**, arja’a, “to postpone” or “to defer”; the Quran speaks of “others deferred (murjawn) until the command of Allah” (Quran 9:106). They deferred deeds out of faith: faith, they said, is affirmation only, so sins do not diminish it and the sinner is a believer of complete faith; the extreme form, Jahm’s, makes faith bare knowledge in the heart. The Salaf distinguished this from the milder “irja’ of the jurists” of Kufah, who left deeds out of the definition of faith yet affirmed that sins are punished and commanded the deeds; they disagreed with the latter as an error in wording and with the former as a heresy (Ibn Taymiyyah, Kitab al-Iman)."),
            .markdown("**Qadariyyah (القَدَرِيَّة)**: named after **qadar (قَدَر)**, the decree, which they denied. The first of them, Ma‘bad al-Juhani and Ghaylan of Damascus, said the matter is “new” and unforeknown, denying that Allah knew deeds before they were done, as Yahya ibn Ya‘mur reported when he brought the matter to Ibn Umar (Sahih Muslim 8); the later Qadariyyah, the Mu‘tazilah, affirmed the knowledge and denied that Allah wills and creates the servants’ acts. Both are set out above under The Qadariyyah."),
            .markdown("**Jabriyyah (الجَبرِيَّة)**: from **jabr (جَبر)**, compulsion: the opposite error, that man has no real will or act at all and is moved like a feather in the wind. This was Jahm’s view. Ahl as-Sunnah stand between the two: Allah creates all things, including the servants’ acts, and the servant truly wills, chooses, and acts, and is justly rewarded or punished; see the question on the decree above."),
            .markdown("**Rafidah (الرَّافِضَة)**: from **rafada (رَفَضَ)**, “to reject” or “to desert.” In 122 AH Zayd ibn Ali ibn al-Husayn (may Allah have mercy on him), the grandson of al-Husayn, rose in Kufah against the Umayyads. Those who had pledged to him demanded that he disavow Abu Bakr and Umar. He refused and said they were his grandfather’s two ministers, so they deserted him, and he said, “You have rejected me (rafadtumuni).” Those who deserted him were called the Rafidah, and the Zaydiyyah are those who stayed with Zayd (ash-Shahrastani, al-Milal wan-Nihal; Ibn Taymiyyah, Minhaj as-Sunnah; Ibn Kathir, al-Bidayah wan-Nihayah, events of 122 AH). The Rafidah reject the Companions who transmitted the religion, and so cast away the very channel it reached us through; see “Answering the Shia” under Salafiyyah."),
            .markdown("**The four errors in the attributes**: **tahrif (تَحرِيف)**, from **ح-ر-ف**, to turn a word from its place, as the Quran says of those who “distort words from their [proper] usages” (Quran 4:46): changing the meaning of a text, such as reading “rose over” as “conquered”; **ta‘til (تَعطِيل)**, from **ع-ط-ل**, to leave idle or empty, as in “an abandoned well” (Quran 22:45): stripping Allah of the attribute altogether; **takyif (تَكيِيف)**, from kayfa, “how”: assigning a manner to the attribute; and **tamthil (تَمثِيل)**, from mithl, “a likeness”: likening it to the attributes of creation. To these the scholars add **tafwid al-ma‘na (تَفوِيض المَعنَى)**, consigning the meaning: the claim that the Salaf recited the texts of the attributes without knowing what they meant. The Salaf consigned only the “how,” never the meaning; Imam Malik’s “the rising is not unknown,” quoted above under Two Roads, says so plainly. Ibn Taymiyyah (may Allah have mercy on him) wrote:"),
            .quote(text: "“The position of the people of tafwid, who claim to be following the Sunnah and the Salaf, is among the worst of the positions of the people of innovation and heresy” (Ibn Taymiyyah, Dar' Ta'arud al-'Aql wan-Naql 1/205).", arabic: "قَولُ أَهلِ التَّفوِيضِ الَّذِينَ يَزعُمُونَ أَنَّهُم مُتَّبِعُونَ لِلسُّنَّةِ وَالسَّلَفِ مِن شَرِّ أَقوَالِ أَهلِ البِدَعِ وَالإِلحَادِ", dimmed: true),
            .markdown("**Istiwa’ (اِستِوَاء)**: from **س-و-ي**; istawa ‘ala means to rise over and settle upon. Allah says of Himself in seven places that He “established Himself above the Throne” (Quran 7:54, 10:3, 13:2, 20:5, 25:59, 32:4, 57:4). In the Book of Tawhid of his Sahih, al-Bukhari related from the Tabi‘i Abu al-‘Aliyah that istawa means “He rose (irtafa‘a),” and from Mujahid that it means “He ascended over (‘ala) the Throne.” The Jahmiyyah denied it, the later kalam schools read it as istawla, “He conquered,” a reading the Salaf rejected and the Arabs never used, and Malik (may Allah have mercy on him) gave the rule that settles it, quoted above."),
            .markdown("**Bid‘ah (بِدعَة)**: from **ب-د-ع**, to originate something with no precedent; Allah is “Originator (Badi‘) of the heavens and the earth” (Quran 2:117) because He made them from nothing. In the religion, a bid‘ah is a newly invented way of worship that has no basis from the Prophet (peace be upon him), practised as though it were part of the religion (ash-Shatibi, al-I‘tisam). He said:"),
            .hadith("bukhari:2697", cite: "Sahih al-Bukhari 2697, Sahih Muslim 1718", arabic: 29...38, english: [4...22]),
            .text("and in his sermons he used to say, “every innovation is misguidance” (Sahih Muslim 867). Innovations in creed are the gravest kind, because they are inventions about Allah Himself."),
            .markdown("**The hadith of the seventy-three sects**: the Prophet (peace be upon him) said:"),
            .hadith("abudawud:4596", cite: "Sunan Abi Dawud 4596; graded hasan sahih by al-Albani", arabic: 26...47, english: [4...35]),
            .text("Together with the report of Mu‘awiyah above, which names the saved sect as the Jama‘ah, this is the foundation of the Salaf’s writing about the sects. Ibn Taymiyyah (may Allah have mercy on him) added a caution in Majmu‘ al-Fatawa: the Prophet counted all seventy-three as “my nation,” so belonging to a deviant sect is a threat of the Fire, not by itself disbelief, and whoever declares every one of the seventy-two sects a disbeliever has opposed the Book, the Sunnah, and the consensus of the Companions and the four imams."),
        ]),
    ]
